const lintWantedEdgeHeadsFirst = `-- name: LintWantedEdgeHeadsFirst :many
WITH excluded AS MATERIALIZED (SELECT unnest($4::uuid[]) AS id)
SELECT l.source_id, l.range_start, octet_length(l.target)::bigint AS target_bytes
FROM page_links l
CROSS JOIN LATERAL (
 SELECT ip.node_id FROM indexed_pages ip
 WHERE ip.node_id=l.source_id AND ip.notebook_id=$1
   AND ip.extractor=$2
   AND l.source_id NOT IN (SELECT id FROM excluded)
   AND l.resolved_id IS NULL AND l.target_key IS NOT NULL
 LIMIT 1
) current_page
WHERE l.notebook_id=$1
ORDER BY l.source_id,l.range_start
LIMIT (SELECT $3::integer)
`

